  1	// Folder navigation shell for the desktop sidebar and embedded sidebar mode.
  2	import type { MouseEvent as ReactMouseEvent, ReactNode } from "react";
  3	import { useDroppable } from "@dnd-kit/core";
  4	import type { TreeItem } from "../model/types";
  5	import { SidebarMenu } from "@/shared/ui/sidebar";
  6	import { TreeNode } from "./tree-node";
  7	import { SidebarFileTreeNode } from "./sidebar-file-tree-node";
  8	import type { NotePreview } from "@typenotes/shared/format";
  9	import { ROOT_ID, dropId, type EdgeSnap } from "../model/tree-dnd";
 10	
 11	const EMPTY_STRING_SET = new Set<string>();
 12	
 13	type FoldersPanelProps = {
 14	  treeData: TreeItem[];
 15	  selectedIds: Set<string>;
 16	  onSelect: (event: ReactMouseEvent, id: string) => void;
 17	  edgeSnap: EdgeSnap;
 18	  expanded: Set<string>;
 19	  onToggle: (event: ReactMouseEvent, id: string) => void;
 20	  onClearSelection: () => void;
 21	  onPaneKeyDown?: (event: React.KeyboardEvent<HTMLDivElement>) => void;
 22	  onPaneClick?: () => void;
 23	  paneBodyRef?: React.Ref<HTMLDivElement>;
 24	  renamingFolder: string | null;
 25	  renameValue: string;
 26	  setRenameValue: (value: string) => void;
 27	  submitRenameFolder: () => void;
 28	  cancelRenameFolder: () => void;
 29	  onContextMenu: (event: ReactMouseEvent, id: string) => void;
 30	  showNotesAsChildren?: boolean;
 31	  selectedNoteIds?: Set<string>;
 32	  onNoteSelect?: (notePath: string, event: ReactMouseEvent, parentPath: string) => void;
 33	  onNoteContextMenu?: (
 34	    event: ReactMouseEvent,
 35	    notePath: string,
 36	    parentPath: string
 37	  ) => void;
 38	  notePreviews?: Record<string, NotePreview>;
 39	  indentationWidth: number;
 40	  topAction?: React.ReactNode;
 41	  sectionTitle?: string;
 42	  footer?: React.ReactNode;
 43	  embedded?: boolean;
 44	};
 45	
 46	export function FoldersPanel({
 47	  treeData,
 48	  selectedIds,
 49	  onSelect,
 50	  edgeSnap,
 51	  expanded,
 52	  onToggle,
 53	  onClearSelection,
 54	  onPaneKeyDown,
 55	  onPaneClick,
 56	  paneBodyRef,
 57	  renamingFolder,
 58	  renameValue,
 59	  setRenameValue,
 60	  submitRenameFolder,
 61	  cancelRenameFolder,
 62	  onContextMenu,
 63	  showNotesAsChildren = false,
 64	  selectedNoteIds = EMPTY_STRING_SET,
 65	  onNoteSelect,
 66	  onNoteContextMenu,
 67	  notePreviews = {},
 68	  indentationWidth,
 69	  topAction,
 70	  sectionTitle,
 71	  footer,
 72	  embedded = false,
 73	}: FoldersPanelProps) {
 74	  const { setNodeRef: setRootDropRef, isOver } = useDroppable({
 75	    id: dropId(ROOT_ID, "inside"),
 76	  });
 77	  const handleNoteSelect =
 78	    onNoteSelect ??
 79	    (() => {
 80	      return;
 81	    });
 82	  const handleNoteContextMenu =
 83	    onNoteContextMenu ??
 84	    (() => {
 85	      return;
 86	    });
 87	
 88	  // The folder tree is rendered in two layouts here: the embedded sidebar and
 89	  // the plain pane. They share the same drop-target root and row mapping.
 90	  const renderTreeNodes = () =>
 91	    treeData.map((node) => (
 92	      <TreeNode
 93	        key={node.id}
 94	        node={node}
 95	        depth={0}
 96	        showNotesAsChildren={showNotesAsChildren}
 97	        selectedNoteIds={selectedNoteIds}
 98	        edgeSnap={edgeSnap}
 99	        expanded={expanded}
100	        onToggle={onToggle}
101	        selectedIds={selectedIds}
102	        onSelect={onSelect}
103	        onNoteSelect={handleNoteSelect}
104	        onNoteContextMenu={handleNoteContextMenu}
105	        notePreviews={notePreviews}
106	        renamingFolder={renamingFolder}
107	        renameValue={renameValue}
108	        setRenameValue={setRenameValue}
109	        submitRenameFolder={submitRenameFolder}
110	        cancelRenameFolder={cancelRenameFolder}
111	        onContextMenu={onContextMenu}
112	        indentationWidth={indentationWidth}
113	      />
114	    ));
115	
116	  const renderDroppablePaneBody = (children: ReactNode) => (
117	    <div className="nav-scroll-area">
118	      <div
119	        ref={(node) => {
120	          setRootDropRef(node);
121	          if (typeof paneBodyRef === "function") {
122	            paneBodyRef(node);
123	          } else if (paneBodyRef && "current" in paneBodyRef) {
124	            paneBodyRef.current = node;
125	          }
126	        }}
127	        className={`pane-body tree-root${isOver ? " drop-inside" : ""}`}
128	        tabIndex={0}
129	        onKeyDownCapture={onPaneKeyDown}
130	        onClick={(event) => {
131	          if (onPaneClick) {
132	            onPaneClick();
133	          }
134	          if (event.target === event.currentTarget) {
135	            onClearSelection();
136	          }
137	        }}
138	      >
139	        {children}
140	      </div>
141	    </div>
142	  );
143	
144	  const sectionContent = (
145	    <div className={embedded ? "pane-section sidebar-folders-section" : "pane-section"}>
146	      {sectionTitle ? <div className="pane-section-title">{sectionTitle}</div> : null}
147	      {renderDroppablePaneBody(
148	        embedded ? (
149	          <SidebarMenu className="sidebar-filetree-menu">
150	            {treeData.length === 0 ? <div className="empty">No folders yet.</div> : null}
151	            {treeData.map((node) => (
152	              <SidebarFileTreeNode
153	                key={node.id}
154	                node={node}
155	                selectedIds={selectedIds}
156	                selectedNoteIds={selectedNoteIds}
157	                showNotesAsChildren={showNotesAsChildren}
158	                expanded={expanded}
159	                onSelect={onSelect}
160	                onToggle={onToggle}
161	                onNoteSelect={handleNoteSelect}
162	                onNoteContextMenu={handleNoteContextMenu}
163	                notePreviews={notePreviews}
164	                renamingFolder={renamingFolder}
165	                renameValue={renameValue}
166	                setRenameValue={setRenameValue}
167	                submitRenameFolder={submitRenameFolder}
168	                cancelRenameFolder={cancelRenameFolder}
169	                onContextMenu={onContextMenu}
170	              />
171	            ))}
172	          </SidebarMenu>
173	        ) : (
174	          <>
175	            {treeData.length === 0 ? <div className="empty">No folders yet.</div> : null}
176	            {renderTreeNodes()}
177	          </>
178	        )
179	      )}
180	    </div>
181	  );
182	
183	  if (embedded) {
184	    return sectionContent;
185	  }
186	
187	  return (
188	    <div className="pane tree-pane nav-pane">
189	      {topAction ? (
190	        <div className="pane-top pane-top-draggable">
191	          <div className="pane-top-drag-region" data-tauri-drag-region aria-hidden />
192	          <div className="pane-top-content">{topAction}</div>
193	        </div>
194	      ) : null}
195	      {sectionContent}
196	      {footer ? <div className="pane-footer">{footer}</div> : null}
197	    </div>
198	  );
199	}

