  1	// Recursive navigation renderer for folder trees and feed buckets.
  2	import type { MouseEvent as ReactMouseEvent } from "react";
  3	import type { EdgeSnap } from "../model/tree-dnd";
  4	import { TreeRow } from "./tree-row";
  5	import { NavNoteRow } from "./nav-note-row";
  6	import type { NotePreview } from "@typenotes/shared/format";
  7	import type { NavigationNode } from "../model/types";
  8	
  9	export type TreeNodeProps = {
 10	  node: NavigationNode;
 11	  depth: number;
 12	  selectedIds: Set<string>;
 13	  selectedNoteIds: Set<string>;
 14	  showNotesAsChildren: boolean;
 15	  edgeSnap: EdgeSnap;
 16	  expanded: Set<string>;
 17	  onSelect: (event: ReactMouseEvent, id: string) => void;
 18	  onToggle: (event: ReactMouseEvent, id: string) => void;
 19	  onNoteSelect: (notePath: string, event: ReactMouseEvent, parentPath: string) => void;
 20	  onNoteContextMenu: (
 21	    event: ReactMouseEvent,
 22	    notePath: string,
 23	    parentPath: string
 24	  ) => void;
 25	  notePreviews: Record<string, NotePreview>;
 26	  renamingFolder?: string | null;
 27	  renameValue?: string;
 28	  setRenameValue?: (value: string) => void;
 29	  submitRenameFolder?: () => void;
 30	  cancelRenameFolder?: () => void;
 31	  onContextMenu: (event: ReactMouseEvent, id: string) => void;
 32	  indentationWidth: number;
 33	  draggable?: boolean;
 34	  feedMode?: boolean;
 35	  renamingEnabled?: boolean;
 36	};
 37	
 38	export function TreeNode({
 39	  node,
 40	  depth,
 41	  selectedIds,
 42	  selectedNoteIds,
 43	  showNotesAsChildren,
 44	  edgeSnap,
 45	  expanded,
 46	  onSelect,
 47	  onToggle,
 48	  onNoteSelect,
 49	  onNoteContextMenu,
 50	  notePreviews,
 51	  renamingFolder = null,
 52	  renameValue = "",
 53	  setRenameValue = () => {
 54	    return;
 55	  },
 56	  submitRenameFolder = () => {
 57	    return;
 58	  },
 59	  cancelRenameFolder = () => {
 60	    return;
 61	  },
 62	  onContextMenu,
 63	  indentationWidth,
 64	  draggable = true,
 65	  feedMode = false,
 66	  renamingEnabled = true,
 67	}: TreeNodeProps) {
 68	  const edgePosition = edgeSnap?.id === node.id ? edgeSnap.position : null;
 69	  const notes = showNotesAsChildren ? node.notes || [] : [];
 70	  const hasNestedItems = node.children.length > 0 || notes.length > 0;
 71	  const isCollapsed = hasNestedItems && !expanded.has(node.id);
 72	  const hasSelectedNote = showNotesAsChildren && selectedNoteIds.size > 0;
 73	  const isFolderVisuallySelected = !hasSelectedNote && selectedIds.has(node.id);
 74	
 75	  return (
 76	    <div className="tree-node">
 77	      <TreeRow
 78	        node={node}
 79	        depth={depth}
 80	        isSelected={isFolderVisuallySelected}
 81	        hasNestedItems={hasNestedItems}
 82	        edgePosition={edgePosition}
 83	        isCollapsed={isCollapsed}
 84	        onSelect={onSelect}
 85	        onToggle={onToggle}
 86	        renaming={renamingFolder === node.id}
 87	        renameValue={renameValue}
 88	        setRenameValue={setRenameValue}
 89	        submitRenameFolder={submitRenameFolder}
 90	        cancelRenameFolder={cancelRenameFolder}
 91	        onContextMenu={onContextMenu}
 92	        indentationWidth={indentationWidth}
 93	        draggable={draggable}
 94	        feedMode={feedMode}
 95	        renamingEnabled={renamingEnabled}
 96	      />
 97	      {hasNestedItems && !isCollapsed && (
 98	        <div className="tree-children">
 99	          {notes.map((note) => (
100	            <NavNoteRow
101	              key={note.path}
102	              note={note}
103	              preview={notePreviews[note.path]}
104	              parentPath={node.id}
105	              depth={depth + 1}
106	              indentationWidth={indentationWidth}
107	              isSelected={selectedNoteIds.has(note.path)}
108	              onSelect={onNoteSelect}
109	              onContextMenu={onNoteContextMenu}
110	              draggable={draggable}
111	              showGuides={feedMode}
112	            />
113	          ))}
114	          {node.children.map((child) => (
115	            <TreeNode
116	              key={child.id}
117	              node={child}
118	              depth={depth + 1}
119	              showNotesAsChildren={showNotesAsChildren}
120	              selectedNoteIds={selectedNoteIds}
121	              edgeSnap={edgeSnap}
122	              expanded={expanded}
123	              onSelect={onSelect}
124	              onToggle={onToggle}
125	              onNoteSelect={onNoteSelect}
126	              onNoteContextMenu={onNoteContextMenu}
127	              notePreviews={notePreviews}
128	              selectedIds={selectedIds}
129	              renamingFolder={renamingFolder}
130	              renameValue={renameValue}
131	              setRenameValue={setRenameValue}
132	              submitRenameFolder={submitRenameFolder}
133	              cancelRenameFolder={cancelRenameFolder}
134	              onContextMenu={onContextMenu}
135	              indentationWidth={indentationWidth}
136	              draggable={draggable}
137	              feedMode={feedMode}
138	              renamingEnabled={renamingEnabled}
139	            />
140	          ))}
141	        </div>
142	      )}
143	    </div>
144	  );
145	}

