  1	// Shared navigation row chrome. Folder trees and feed buckets both use this
  2	// surface; the parent decides which behaviors are enabled.
  3	import type { MouseEvent as ReactMouseEvent } from "react";
  4	import { useCallback } from "react";
  5	import { useDraggable, useDroppable } from "@dnd-kit/core";
  6	import { CSS } from "@dnd-kit/utilities";
  7	import { CalendarDays } from "lucide-react";
  8	import type { NavigationNode } from "../model/types";
  9	import type { DragData } from "@typenotes/shared/types";
 10	import { dropId } from "../model/tree-dnd";
 11	
 12	export type TreeRowProps = {
 13	  node: NavigationNode;
 14	  depth: number;
 15	  isSelected: boolean;
 16	  hasNestedItems: boolean;
 17	  edgePosition: "before" | "after" | null;
 18	  isCollapsed: boolean;
 19	  onSelect: (event: ReactMouseEvent, id: string) => void;
 20	  onToggle: (event: ReactMouseEvent, id: string) => void;
 21	  renaming?: boolean;
 22	  renameValue?: string;
 23	  setRenameValue?: (value: string) => void;
 24	  submitRenameFolder?: () => void;
 25	  cancelRenameFolder?: () => void;
 26	  onContextMenu: (event: ReactMouseEvent, id: string) => void;
 27	  indentationWidth: number;
 28	  draggable?: boolean;
 29	  feedMode?: boolean;
 30	  renamingEnabled?: boolean;
 31	};
 32	
 33	export function TreeRow({
 34	  node,
 35	  depth,
 36	  isSelected,
 37	  hasNestedItems,
 38	  edgePosition,
 39	  isCollapsed,
 40	  onSelect,
 41	  onToggle,
 42	  renaming = false,
 43	  renameValue = "",
 44	  setRenameValue = () => {
 45	    return;
 46	  },
 47	  submitRenameFolder = () => {
 48	    return;
 49	  },
 50	  cancelRenameFolder = () => {
 51	    return;
 52	  },
 53	  onContextMenu,
 54	  indentationWidth,
 55	  draggable = true,
 56	  feedMode = false,
 57	  renamingEnabled = true,
 58	}: TreeRowProps) {
 59	  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
 60	    id: node.id,
 61	    data: { type: "folder", path: node.id } satisfies DragData,
 62	    disabled: !draggable,
 63	  });
 64	  const { setNodeRef: setDropRef, isOver } = useDroppable({
 65	    id: dropId(node.id, "inside"),
 66	    data: { type: "folder", path: node.id } satisfies DragData,
 67	    disabled: !draggable,
 68	  });
 69	
 70	  const setRefs = useCallback(
 71	    (element: HTMLDivElement | null) => {
 72	      setNodeRef(element);
 73	      setDropRef(element);
 74	    },
 75	    [setNodeRef, setDropRef]
 76	  );
 77	
 78	  const style = {
 79	    transform: isDragging ? undefined : CSS.Translate.toString(transform),
 80	    paddingLeft: 12 + depth * indentationWidth,
 81	  } as React.CSSProperties;
 82	  const guideBaseLeft = feedMode
 83	    ? 12 + indentationWidth / 2
 84	    : 12 + 20 + 6 + 8;
 85	
 86	  return (
 87	    <div
 88	      ref={setRefs}
 89	      style={style}
 90	      className={`item-row folder-row${feedMode ? " feed-bucket-row" : ""}${
 91	        isSelected ? " selected" : ""
 92	      }${
 93	        isDragging ? " is-dragging" : ""
 94	      }${isOver && !edgePosition ? " drop-inside" : ""}${
 95	        edgePosition === "before" ? " drop-before" : ""
 96	      }${edgePosition === "after" ? " drop-after" : ""}`}
 97	      data-folder={node.id}
 98	      onClick={(event) => {
 99	        const target = event.target as HTMLElement | null;
100	        if (target && target.closest(".tree-toggle, .rename-input")) {
101	          return;
102	        }
103	        onSelect(event, node.id);
104	      }}
105	      onContextMenu={(event) => {
106	        onContextMenu(event, node.id);
107	      }}
108	      {...listeners}
109	      {...attributes}
110	    >
111	      {depth > 0 && (
112	        <span className="tree-guides" aria-hidden>
113	          {Array.from({ length: depth }, (_, index) => (
114	            <span
115	              key={`depth-${index}`}
116	              className="tree-guide-vert"
117	              style={{ left: guideBaseLeft + index * indentationWidth }}
118	            />
119	          ))}
120	        </span>
121	      )}
122	      {hasNestedItems ? (
123	        <button
124	          type="button"
125	          className={`icon-btn tree-toggle${isCollapsed ? " is-collapsed" : ""}`}
126	          onClick={(event) => {
127	            event.stopPropagation();
128	            onToggle(event, node.id);
129	          }}
130	          onPointerDown={(event) => event.stopPropagation()}
131	          onMouseDown={(event) => event.stopPropagation()}
132	          aria-label={isCollapsed ? "Expand folder" : "Collapse folder"}
133	        >
134	          <svg viewBox="0 0 16 16" aria-hidden="true">
135	            <path d="M6 4l4 4-4 4" fill="none" stroke="currentColor" strokeWidth="1.6" />
136	          </svg>
137	        </button>
138	      ) : (
139	        <span className="icon-spacer" aria-hidden />
140	      )}
141	      {!renaming && (
142	        <span className="folder-glyph" aria-hidden>
143	          {feedMode ? (
144	            <CalendarDays size={15} />
145	          ) : hasNestedItems && !isCollapsed ? (
146	            <svg viewBox="0 0 24 24">
147	              <path
148	                d="M3 8a2.5 2.5 0 0 1 2.5-2.5h4L11.4 7h7.1A2.5 2.5 0 0 1 21 9.5V11"
149	                fill="none"
150	                stroke="currentColor"
151	                strokeWidth="1.5"
152	                strokeLinecap="round"
153	                strokeLinejoin="round"
154	              />
155	              <path
156	                d="M2.8 10.5h18.4a1 1 0 0 1 .96 1.28l-1.65 5.5A2.5 2.5 0 0 1 18.1 19H5.9a2.5 2.5 0 0 1-2.4-1.72l-1.65-5.5a1 1 0 0 1 .95-1.28z"
157	                fill="none"
158	                stroke="currentColor"
159	                strokeWidth="1.5"
160	                strokeLinejoin="round"
161	              />
162	            </svg>
163	          ) : (
164	            <svg viewBox="0 0 24 24">
165	              <path
