 32	
 33	export function TreeRow({
 34	  node,
 35	  depth,
 36	  isSelected,
 37	  hasNestedItems,
 38	  edgePosition,
 39	  isCollapsed,
 40	  onSelect,
 41	  onToggle,
 42	  renaming = false,
