 51	    return;
 52	  },
 53	  onContextMenu,
 54	  indentationWidth,
 55	  draggable = true,
 56	  feedMode = false,
 57	  renamingEnabled = true,
 58	}: TreeRowProps) {
 59	  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
 60	    id: node.id,
 61	    data: { type: "folder", path: node.id } satisfies DragData,
 62	    disabled: !draggable,
 63	  });
 64	  const { setNodeRef: setDropRef, isOver } = useDroppable({
