 72	      setNodeRef(element);
 73	      setDropRef(element);
 74	    },
 75	    [setNodeRef, setDropRef]
 76	  );
 77	
 78	  const style = {
 79	    transform: isDragging ? undefined : CSS.Translate.toString(transform),
 80	    paddingLeft: 12 + depth * indentationWidth,
 81	  } as React.CSSProperties;
 82	  const guideBaseLeft = feedMode
 83	    ? 12 + indentationWidth / 2
