105	      onContextMenu={(event) => {
106	        onContextMenu(event, node.id);
107	      }}
108	      {...listeners}
109	      {...attributes}
110	    >
111	      {depth > 0 && (
112	        <span className="tree-guides" aria-hidden>
113	          {Array.from({ length: depth }, (_, index) => (
