  1	// Embedded-sidebar renderer for the same navigation tree shape as TreeNode.
  2	import type { MouseEvent as ReactMouseEvent } from "react";
  3	import { ChevronRight, File, Folder, Mic, PenLine } from "lucide-react";
  4	import { Collapsible, CollapsibleContent } from "@/shared/ui/collapsible";
  5	import {
  6	  SidebarMenuBadge,
  7	  SidebarMenuButton,
  8	  SidebarMenuItem,
  9	  SidebarMenuSub,
 10	  SidebarMenuSubButton,
 11	} from "@/shared/ui/sidebar";
 12	import type { NavigationNode } from "../model/types";
 13	import type { NotePreview } from "@typenotes/shared/format";
 14	
 15	type SidebarFileTreeNodeProps = {
 16	  node: NavigationNode;
 17	  selectedIds: Set<string>;
 18	  selectedNoteIds: Set<string>;
 19	  showNotesAsChildren: boolean;
 20	  expanded: Set<string>;
 21	  onSelect: (event: ReactMouseEvent, id: string) => void;
 22	  onToggle: (event: ReactMouseEvent, id: string) => void;
 23	  onNoteSelect: (notePath: string, event: ReactMouseEvent, parentPath: string) => void;
 24	  onNoteContextMenu: (
 25	    event: ReactMouseEvent,
 26	    notePath: string,
 27	    parentPath: string
 28	  ) => void;
 29	  notePreviews: Record<string, NotePreview>;
 30	  renamingFolder?: string | null;
 31	  renameValue?: string;
 32	  setRenameValue?: (value: string) => void;
 33	  submitRenameFolder?: () => void;
 34	  cancelRenameFolder?: () => void;
 35	  onContextMenu: (event: ReactMouseEvent, id: string) => void;
 36	};
 37	
 38	/**
 39	 * The embedded-sidebar counterpart to {@link TreeNode}: renders the folder tree
 40	 * (and, optionally, notes as children) using the shadcn Sidebar primitives and
 41	 * without drag-and-drop. Used by FoldersPanel's `embedded` mode.
 42	 */
 43	export function SidebarFileTreeNode({
 44	  node,
 45	  selectedIds,
 46	  selectedNoteIds,
 47	  showNotesAsChildren,
 48	  expanded,
 49	  onSelect,
 50	  onToggle,
 51	  onNoteSelect,
 52	  onNoteContextMenu,
 53	  notePreviews,
 54	  renamingFolder = null,
 55	  renameValue = "",
 56	  setRenameValue = () => {
 57	    return;
 58	  },
 59	  submitRenameFolder = () => {
 60	    return;
 61	  },
 62	  cancelRenameFolder = () => {
 63	    return;
 64	  },
 65	  onContextMenu,
 66	}: SidebarFileTreeNodeProps) {
 67	  const notes = showNotesAsChildren ? node.notes || [] : [];
 68	  const hasNestedItems = node.children.length > 0 || notes.length > 0;
 69	  const isExpanded = !hasNestedItems || expanded.has(node.id);
 70	  const isRenaming = renamingFolder === node.id;
 71	
 72	  return (
 73	    <SidebarMenuItem>
 74	      <Collapsible open={isExpanded} className="group/collapsible">
 75	        <SidebarMenuButton
 76	          isActive={selectedIds.has(node.id)}
 77	          className="sidebar-filetree-button"
 78	          asChild
 79	        >
 80	          <div
 81	            className="sidebar-filetree-button-inner"
 82	            onClick={(event) => {
 83	              onSelect(event, node.id);
 84	            }}
 85	            onContextMenu={(event) => {
 86	              onContextMenu(event, node.id);
 87	            }}
 88	          >
 89	            {hasNestedItems ? (
 90	              <button
 91	                type="button"
 92	                className="sidebar-filetree-toggle"
 93	                onClick={(event) => {
 94	                  event.stopPropagation();
 95	                  onToggle(event, node.id);
 96	                }}
 97	                aria-label={isExpanded ? "Collapse folder" : "Expand folder"}
 98	              >
 99	                <ChevronRight
100	                  className={`sidebar-filetree-chevron${isExpanded ? " is-open" : ""}`}
101	                />
102	              </button>
103	            ) : (
104	              <span className="sidebar-filetree-toggle-spacer" aria-hidden />
105	            )}
106	            <Folder />
107	            {isRenaming ? (
108	              <input
109	                className="rename-input sidebar-filetree-rename-input"
110	                value={renameValue}
111	                autoFocus
112	                onChange={(event) => setRenameValue(event.target.value)}
113	                onBlur={submitRenameFolder}
114	                onKeyDown={(event) => {
115	                  event.stopPropagation();
116	                  if (event.key === "Enter") {
117	                    submitRenameFolder();
118	                  }
119	                  if (event.key === "Escape") {
120	                    cancelRenameFolder();
121	                  }
122	                }}
123	                onMouseDown={(event) => event.stopPropagation()}
124	                onClick={(event) => event.stopPropagation()}
125	              />
126	            ) : (
127	              <span>{node.name}</span>
128	            )}
129	          </div>
130	        </SidebarMenuButton>
131	        {!isRenaming && node.noteCount ? <SidebarMenuBadge>{node.noteCount}</SidebarMenuBadge> : null}
132	        {hasNestedItems ? (
133	          <CollapsibleContent>
134	            <SidebarMenuSub>
135	              {notes.map((note) => {
136	                const preview = notePreviews[note.path];
137	                return (
138	                  <SidebarMenuSubButton
139	                    key={note.path}
140	                    asChild
141	                    isActive={selectedNoteIds.has(note.path)}
142	                    size="md"
143	                  >
144	                    <button
145	                      type="button"
146	                      className="sidebar-filetree-note-button"
147	                      onClick={(event) => onNoteSelect(note.path, event, node.id)}
148	                      onContextMenu={(event) => onNoteContextMenu(event, note.path, node.id)}
149	                    >
150	                      <File />
151	                      <span>{preview?.title || note.name}</span>
152	                      {preview?.isRecording ? (
153	                        <Mic size={12} className="sidebar-filetree-note-mic" />
154	                      ) : preview?.isHandwriting ? (
155	                        <PenLine size={12} className="sidebar-filetree-note-mic" />
156	                      ) : null}
157	                    </button>
158	                  </SidebarMenuSubButton>
159	                );
160	              })}
161	              {node.children.map((child) => (
162	                <SidebarFileTreeNode
163	                  key={child.id}
164	                  node={child}
165	                  selectedIds={selectedIds}
166	                  selectedNoteIds={selectedNoteIds}
167	                  showNotesAsChildren={showNotesAsChildren}
168	                  expanded={expanded}
169	                  onSelect={onSelect}
170	                  onToggle={onToggle}
171	                  onNoteSelect={onNoteSelect}
172	                  onNoteContextMenu={onNoteContextMenu}
173	                  notePreviews={notePreviews}
174	                  renamingFolder={renamingFolder}
175	                  renameValue={renameValue}
176	                  setRenameValue={setRenameValue}
177	                  submitRenameFolder={submitRenameFolder}
178	                  cancelRenameFolder={cancelRenameFolder}
179	                  onContextMenu={onContextMenu}
180	                />
181	              ))}
182	            </SidebarMenuSub>
183	          </CollapsibleContent>
184	        ) : null}
185	      </Collapsible>
186	    </SidebarMenuItem>
187	  );
188	}

