119	  const handleDragMove = useCallback(
120	    (event: DragMoveEvent) => {
121	      if (activeDrag.current?.type !== "folder") return;
122	      const { active, over } = event;
123	      if (!active || !over) {
124	        setEdgeSnap(null);
125	        if (expandTimeoutRef.current) {
126	          window.clearTimeout(expandTimeoutRef.current);
127	          expandTimeoutRef.current = null;
128	        }
129	        expandTargetRef.current = null;
130	        return;
131	      }
132	      const dropTarget = parseDropTargetId(over.id);
133	      if (!dropTarget || dropTarget.type !== "item" || dropTarget.position !== "inside") {
134	        setEdgeSnap(null);
135	        if (expandTimeoutRef.current) {
136	          window.clearTimeout(expandTimeoutRef.current);
137	          expandTimeoutRef.current = null;
138	        }
139	        expandTargetRef.current = null;
140	        return;
141	      }
142	
143	      // Spring-load: hovering a collapsed folder for 500ms auto-expands it, so
144	      // you can drill into a nested folder mid-drag without dropping first.
145	      const overNode = getNodeById(treeData, dropTarget.itemId);
146	      const hasChildren = Boolean(overNode?.children && overNode.children.length > 0);
147	      const isCollapsed = hasChildren && !expanded.has(dropTarget.itemId);
148	      if (isCollapsed) {
149	        if (expandTargetRef.current !== dropTarget.itemId) {
150	          if (expandTimeoutRef.current) window.clearTimeout(expandTimeoutRef.current);
151	          expandTargetRef.current = dropTarget.itemId;
152	          expandTimeoutRef.current = window.setTimeout(() => {
153	            setExpanded((prev) => {
