174	      // Prefer the live pointer position (drag-start point + dnd-kit delta);
175	      // fall back to the dragged row's center when the drag wasn't mouse-driven.
176	      let pointerY: number | null = null;
177	      if (dragStartPoint.current && typeof event.delta?.y === "number") {
